def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-5]), fmt([3, 2, 1]), fmt([0, 0, 0]), fmt([1, 2, 3, 4, 5]), fmt([-1, -2, -3, -4])]
    for n in (2, 3, 4, 6, 9, 15, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(-10**5, 10**5) for _ in range(n)]))
    tests.append(fmt([10**5 - (i % 3) for i in range(n)]))
    tests.append(fmt([-10**5 + (i % 7) for i in range(n)]))
    tests.append(fmt([rng.randint(0, 10**5) for _ in range(n)]))
    return tests

